solution.solution.cpp:
#include <cstddef>
#include <optional>
#include <stdexcept>
#include <vector>

enum class Protect { NoAccess, ReadOnly, ReadWrite };
struct RegionInfo { std::size_t start; std::size_t size; bool committed; Protect protect; };

std::size_t alignUp(std::size_t value, std::size_t alignment)
{
    return (value + alignment - 1) & ~(alignment - 1);
}

class VirtualRegion
{
public:
    explicit VirtualRegion(std::size_t requested, std::size_t pageSize = 4096)
        : pageSize_{ pageSize }, pages_(alignUp(requested, pageSize) / pageSize)
    {
    }

    std::size_t size() const { return pages_.size() * pageSize_; }

    bool commit(std::size_t offset, std::size_t length, Protect protect)
    {
        std::size_t first{}, last{};
        if (!range(offset, length, first, last)) return false;
        for (std::size_t i{ first }; i <= last; ++i)
        {
            if (!pages_[i].committed) pages_[i] = { true, protect };
        }
        return true;
    }

    bool decommit(std::size_t offset, std::size_t length)
    {
        std::size_t first{}, last{};
        if (!range(offset, length, first, last)) return false;
        for (std::size_t i{ first }; i <= last; ++i) pages_[i] = { false, Protect::NoAccess };
        return true;
    }

    std::optional<Protect> protect(std::size_t offset, std::size_t length, Protect protect)
    {
        std::size_t first{}, last{};
        if (!range(offset, length, first, last)) return std::nullopt;
        for (std::size_t i{ first }; i <= last; ++i)
            if (!pages_[i].committed) return std::nullopt;
        const Protect old{ pages_[first].protect };
        for (std::size_t i{ first }; i <= last; ++i) pages_[i].protect = protect;
        return old;
    }

    bool canRead(std::size_t offset) const
    {
        if (offset >= size()) return false;
        const Page& p{ pages_[offset / pageSize_] };
        return p.committed && p.protect != Protect::NoAccess;
    }

    bool canWrite(std::size_t offset) const
    {
        if (offset >= size()) return false;
        const Page& p{ pages_[offset / pageSize_] };
        return p.committed && p.protect == Protect::ReadWrite;
    }

    RegionInfo query(std::size_t offset) const
    {
        if (offset >= size()) throw std::out_of_range("offset is past the reservation");
        const std::size_t first{ offset / pageSize_ };
        std::size_t end{ first + 1 };
        while (end < pages_.size() && pages_[end].committed == pages_[first].committed && pages_[end].protect == pages_[first].protect) ++end;
        return { first * pageSize_, (end - first) * pageSize_, pages_[first].committed, pages_[first].protect };
    }

private:
    struct Page
    {
        bool committed{ false };
        Protect protect{ Protect::NoAccess };
    };

    bool range(std::size_t offset, std::size_t length, std::size_t& first, std::size_t& last) const
    {
        if (length == 0 || offset >= size() || length > size() - offset) return false;
        first = offset / pageSize_;
        last = (offset + length - 1) / pageSize_;
        return true;
    }

    std::size_t pageSize_;
    std::vector<Page> pages_;
};

unitTests:
bool same(const RegionInfo& r, std::size_t start, std::size_t size, bool committed, Protect p) {
    return r.start == start && r.size == size && r.committed == committed && r.protect == p;
}
TEST("rounding") {
    CHECK_EQ(alignUp(10000, 4096), 12288u);
    CHECK_EQ(alignUp(4096, 4096), 4096u);
    CHECK_EQ(alignUp(0, 65536), 0u);
    CHECK_EQ(alignUp(1, 65536), 65536u);
    CHECK_EQ(VirtualRegion(10000).size(), 12288u);
    CHECK_EQ(VirtualRegion(65536).size(), 65536u);
}
TEST("reserved pages allow nothing") {
    VirtualRegion r{ 65536 };
    CHECK(!r.canRead(0));
    CHECK(!r.canWrite(100));
    CHECK(same(r.query(0), 0, 65536, false, Protect::NoAccess));
    CHECK(same(r.query(5000), 4096, 65536 - 4096, false, Protect::NoAccess));
}
TEST("committing whole pages") {
    VirtualRegion r{ 65536 };
    CHECK(r.commit(100, 10, Protect::ReadWrite));
    CHECK(r.canWrite(0) && r.canWrite(4095));
    CHECK(!r.canRead(4096));
    CHECK(r.commit(4000, 200, Protect::ReadOnly));
    CHECK(r.canWrite(0));
    CHECK(r.canRead(4096) && !r.canWrite(4096));
    CHECK(same(r.query(0), 0, 4096, true, Protect::ReadWrite));
    CHECK(same(r.query(5000), 4096, 4096, true, Protect::ReadOnly));
    CHECK(same(r.query(8192), 8192, 65536 - 8192, false, Protect::NoAccess));
}
TEST("changing protection") {
    VirtualRegion r{ 65536 };
    r.commit(0, 3 * 4096, Protect::ReadWrite);
    CHECK(r.protect(4096, 4096, Protect::ReadOnly) == std::optional<Protect>{ Protect::ReadWrite });
    CHECK(!r.canWrite(4096) && r.canWrite(8192));
    CHECK(r.protect(0, 3 * 4096, Protect::NoAccess) == std::optional<Protect>{ Protect::ReadWrite });
    CHECK(!r.canRead(0));
    CHECK(!r.protect(8192, 8192, Protect::ReadOnly).has_value());
    CHECK(same(r.query(0), 0, 3 * 4096, true, Protect::NoAccess));
}
TEST("decommitting") {
    VirtualRegion r{ 65536 };
    r.commit(0, 65536, Protect::ReadWrite);
    CHECK(r.decommit(4096 + 1, 1));
    CHECK(!r.canRead(4096) && r.canRead(0) && r.canRead(8192));
    CHECK(same(r.query(0), 0, 4096, true, Protect::ReadWrite));
    CHECK(same(r.query(4096), 4096, 4096, false, Protect::NoAccess));
    CHECK(same(r.query(9000), 8192, 65536 - 8192, true, Protect::ReadWrite));
}
TEST("ranges that are refused") {
    VirtualRegion r{ 8192 };
    CHECK(!r.commit(0, 0, Protect::ReadWrite));
    CHECK(!r.commit(4096, 8192, Protect::ReadWrite));
    CHECK(!r.commit(8192, 1, Protect::ReadWrite));
    CHECK(!r.decommit(9000, 1));
    CHECK(!r.canRead(4096));
    CHECK(!r.canRead(100000));
    CHECK_THROWS_AS(r.query(8192), std::out_of_range);
    CHECK(r.commit(4096, 4096, Protect::ReadOnly));
    CHECK(r.canRead(8191));
}

